Install dependencies
This simply restores the {renv} library. Once again, in this example it is superfluous as we run everything from the same repo, but in real-life you will likely need to do this.

info(logger, 'Restoring renv')  
tryCatch({  
  renv::restore()  
},  
 error = function(errMessage){  
  fatal(logger, errMessage)  
  stop(errMessage)  
 }  
)  
info(logger, 'renv restored successfully')

If your model code base has unit tests, this is a good time to run them.

Re-train the model
We might want to do this if we have different training data in this environment. On the other hand, we do not want to do this if the model is a complex one that takes a lot of time and resources to train. In that case, we would use the trained model directly, for instance, by using the rds (or pickle) file.

info(logger, 'Training model')  
tryCatch({  
  source(here::here('deployment', 'model_dev', 'R', '01_model_dev.R'))  
},  
 error = function(errMessage){  
  fatal(logger, errMessage)  
  stop(errMessage)  
 }  
)  
info(logger, 'Model trained')

Save the model to the pins board
This is another easy step. Simply save the model as a pin. Note that this is acceptable for our example, but in a real-life example, you might want to consider alternative storage options, depending on the size and type of model you are dealing with.

info(logger, 'Pin the vetiver model object')  
tryCatch({  
  board %&gt;%  
    vetiver::vetiver_pin_write(vetiver_model = vetiver_flights_fit)  
},  
 error = function(errMessage){  
    fatal(logger, errMessage)  
    stop(errMessage)  
 }  
)  
info(logger, 'Vetiver model object added to pins')

Deploy the model as a REST API
In our example, we comment this out, as we simply run the model locally. You can start the plumber API using the bash script startAPI.bash (you might need to make a couple of changes for Unix or Windows systems).
There is another reason why we did not deploy the {plumber} API generated by {vetiver} “as is” is because that API does not contain any logging facility. Without logging, we cannot do any monitoring of the model. You could build a facade API that simply logs requests and responses and all it does is re-route the traffic to the model API, but that will add a bit of latency. Personally, I just prefer to have the log machinery embedded in the model API.

info(logger, 'Deploying model as vetiver API')  
tryCatch({  
  # In this example, we will use vetiver::vetiver_write_plumber().  
  # In real life, you probably want to deploy to rsconnect with  
  # vetiver::vetiver_deploy_rsconnect()  
  # vetiver::vetiver_write_plumber(board, 'flights_fit')  
},  
 error = function(errMessage){  
  fatal(logger, errMessage)  
  stop(errMessage)  
 }  
)  
info(logger, 'Model deployed as vetiver API')

Smoke test the deployment
The next step is to make sure that the API is up and running. We do three tests:

Ping: expect a code 200 response.
Valid request: expect a code 200 reponse.
Invalid request: expect a code 500 response.

As you see, in this phase, we do not do any validation of the model. We just check if the API is up and running. Note that I did not use testthat for these tests as I wanted full control over what gets logged and what happens when a test fails.

Set up and ping test

info(logger, 'starting smoke tests')  
test_data &lt;- board %&gt;% pins::pin_read('test_data')  
rootUrl &lt;- "&lt;http://127.0.0.1:4023/&gt;"  

info(logger, 'test ping endpoint')  
tryCatch({  
  r &lt;- httr::GET(paste0(rootUrl, "ping"))$status_code  
},  
 error = function(errMessage){  
  fatal(logger, errMessage)  
  stop(errMessage)  
 }  
)  
if(r != 200){  
  errMessage &lt;- 'ping did not return 200'  
  fatal(logger, errMessage)  
  stop(errMessage)  
}  
info(logger, 'ping test successful') request  



Valid request

info(logger, 'test valid request')  
requestBody_OK &lt;- jsonlite::toJSON(test_data[1,])  

tryCatch({  
  r &lt;- httr::POST(paste0(rootUrl, "predict_flights"),  
                body = requestBody_OK,  
                encode = "json")$status_code  
},  
 error = function(errMessage){  
  fatal(logger, errMessage)  
  stop(errMessage)  
 }  
)  
if(r != 200){  
  errMessage &lt;- 'predict did not return 200 for a valid request'  
  fatal(logger, errMessage)  
  stop(errMessage)  
}  
info(logger, 'valid request test successful')



Invalid request

info(logger, 'test invalid request')  
requestBody_WRONG &lt;- jsonlite::toJSON(mtcars[1,])  

tryCatch({  
  r &lt;- httr::POST(paste0(rootUrl, "predict_flights"),  
                body = requestBody_OK,  
                encode = "json")$status_code  
},  
 error = function(errMessage){  
  fatal(logger, errMessage)  
  stop(errMessage)  
 }  
)  
if(r != 500){  
  errMessage &lt;- 'predict did not return 500 for an invalid request'  
  fatal(logger, errMessage)  
  stop(errMessage)  
}  
info(logger, 'invalid request test successful')

Testing

Test for accuracy using a test data set
In this test, we submit a test dataset to the prediction endpoint of the API. We then measure accuracy using the yardstick package and ensure that the accuracy we got is at least equal to the minimum required by the business. In our example, we defined that to be 80%, and this value is set in the R markdown yaml preamble.

info(logger, 'test accuracy')  
requestBody &lt;- jsonlite::toJSON(test_data)  
tryCatch({  
  preds &lt;- httr::POST(paste0(rootUrl, "predict_flights"),  
                      body = requestBody,  
                      encode = "json")  
    preds &lt;- httr::content(preds)  
    preds &lt;- t(as.data.frame(preds))  
    final_df &lt;- data.frame(preds = as.factor(preds[,1]),  
                           truths = as.factor(test_data$arr_delay))  
  model_accuracy &lt;- final_df %&gt;% yardstick::accuracy(preds, truths)  
}, error = function(errMessage){  
  fatal(logger, errMessage)  
  stop(errMessage)  
 }  
)  

if(model_accuracy$.estimate[1] &lt; params$minAcceptableAccuracy){  
  fatal(logger, 'Insufficient accuracy')  
  stop('Insufficient accuracy')  
}  
info(logger, 'accuracy tested successfully')



Test for drift using a test data set
This test ensures that the test data we use is representative of the training data. We use the Kolmogorov-Smirnov test to compare the distribution of a few features between the test and the train dataset.
Note that we do have some failure here, caused by how we initially split the data between train and test (and also probably to the fact that this is not the best application for this test). I therefore simply log the events as errors, so that they are visible, but I do not fail the pipeline. In a real-world application, you might want to actually fail the pipeline if you have similar issues.

info(logger, 'starting Kolmogorov-Smirnov test')  
columnsToTest &lt;- c("origin", "dest", "air_time", "distance", "carrier")  
test_data &lt;- board %&gt;% pins::pin_read('test_data')  
train_data &lt;- board %&gt;% pins::pin_read('train_data')  

convertToInteger &lt;- function(vec){  
  if(is.factor(vec) || is.character(vec)){  
    vec &lt;- as.character(vec)    seqNames &lt;- unique(vec)  
    for(i in seq_along(seqNames)){  
      vec[vec == seqNames[i]] &lt;- i  
    }  
  }  
  vec &lt;- as.integer(vec)  
  return(vec)  
}  
for(thisCol in columnsToTest){  
  dist1 &lt;- convertToInteger(test_data[[thisCol]])  
  dist2 &lt;- convertToInteger(train_data[[thisCol]])  
  if (ks.test(dist1, dist2)$p.value &gt;= 0.05){  
    error(logger,  
          paste0('column ',  
                 thisCol,  
                 ' did not pass the Kolmogorov-Smirnov test')  
    )  
  }  
}  
info(logger, 'Kolmogorov-Smirnov test ended')

In-code flags
In-code flags look something like this:

#if/else option
if (runEnv == "prod"){
  varVal &lt;- 1
} else if(runEnv == "dev"){
  varVal &lt;- 2
} else {
  varVal &lt;-3
}

# switch option
varVal &lt;- switch(runEnv,
                 "prod" = 1,
                 "dev" = 2,
                 3
)

In-code flags are a great deployment pattern tool, but this is not when they should be used. Using in-code flags to manage the configuration is just marginally better than hardcoding the values. They solve the problem of having different values for different environments, but they do not allow you to quickly change said values. Also, imagine somebody decides to change the name prod to production. Not fun…

Caching reactive outputs with bindCache()
renderCachedPlot() is specific to plots. What if the expensive work is not a plot at all?
Consider this app:
library(shiny)

ui &lt;- fluidPage(
  sidebarLayout(
    sidebarPanel(
      radioButtons("x", "y", choices = c(3, 4, 5), selected = 3)
    ),
    mainPanel(
      tagList(
        div("2 * x:"),
        verbatimTextOutput("txt")
      )
    )
  )
)

server &lt;- function(input, output, session) {
  r &lt;- reactive({
    Sys.sleep(2)
    2 * as.numeric(input$x)
  })

  output$txt &lt;- renderText(r())
}

shinyApp(ui = ui, server = server)
The calculation itself is trivial, but Sys.sleep(2) simulates an expensive operation. Each time the user changes the input, the app waits two seconds. If they return to a previous selection, it still waits.
For non-plot outputs, bindCache() is often the right solution.
library(shiny)
library(magrittr)

shinyOptions(cache = cachem::cache_disk("./myapp-bindcache"))

ui &lt;- fluidPage(
  sidebarLayout(
    sidebarPanel(
      radioButtons("x", "y", choices = c(3, 4, 5), selected = 3)
    ),
    mainPanel(
      tagList(
        div("2 * x:"),
        verbatimTextOutput("txt")
      )
    )
  )
)

server &lt;- function(input, output, session) {
  r &lt;- reactive({
    Sys.sleep(2)
    2 * as.numeric(input$x)
  }) %&gt;%
    bindCache(input$x)

  output$txt &lt;- renderText(r())
}

shinyApp(ui = ui, server = server)
What changed:

We configured a cache location with shinyOptions().
We added bindCache(input$x) to the reactive expression.

bindCache() uses its arguments to build the cache key. In this case, the result depends only on input$x, so that is all we need.
The behavior is straightforward:

The first time a value is requested, the reactive computes normally.
Later requests for the same value can be served from cache.

This is useful whenever you want caching for outputs that are not ggplot2 graphics, including text, tables, and intermediate reactive results.

Caching function results with memoise
There is another common case: the expensive work lives inside a normal R function. In that situation, memoise can be a better fit.
Start with this example:
library(shiny)

double_x &lt;- function(x) {
  Sys.sleep(2)
  x * 2
}

ui &lt;- fluidPage(
  sidebarLayout(
    sidebarPanel(
      radioButtons("x", "x", choices = c(3, 4, 5), selected = 3)
    ),
    mainPanel(
      tagList(
        div("2 * x:"),
        verbatimTextOutput("txt")
      )
    )
  )
)

server &lt;- function(input, output, session) {
  r &lt;- reactive({
    double_x(as.numeric(input$x))
  })

  output$txt &lt;- renderText(r())
}

shinyApp(ui = ui, server = server)
Again, the app repeats the same expensive work every time.
Now wrap the function with memoise.
library(shiny)
library(memoise)

cd &lt;- cache_filesystem("./myapp-memoise")

double_x &lt;- function(x) {
  Sys.sleep(2)
  x * 2
}

mmn &lt;- memoise(double_x, cache = cd)

ui &lt;- fluidPage(
  sidebarLayout(
    sidebarPanel(
      radioButtons("x", "x", choices = c(3, 4, 5), selected = 3)
    ),
    mainPanel(
      tagList(
        div("2 * x:"),
        verbatimTextOutput("txt")
      )
    )
  )
)

server &lt;- function(input, output, session) {
  r &lt;- reactive({
    mmn(as.numeric(input$x))
  })

  output$txt &lt;- renderText(r())
}

shinyApp(ui = ui, server = server)
The changes are:

We define a filesystem cache with cache_filesystem().
We wrap the expensive function with memoise().
The app calls the memoised version instead of the original function.

If mmn(3) has already been computed once, the cached result can be returned the next time mmn(3) is called.
This pattern is especially useful when expensive logic is already encapsulated in functions. It also generalizes beyond Shiny, which is one of the reasons memoise is so handy.
One practical tip: Shiny modules are functions too. If module initialization or internal setup is expensive, memoise can sometimes help there as well.

Inheritance
RC supports inheritance through the contains argument of the constructor. Let’s consider our Dog subclass.

Dog &lt;- setRefClass(
  "Dog",
  contains = 'Animals',
  fields=c(name="character",
           age = 'numeric'),
  methods=list(
    initialize = function(name, age){
      validate(name, age)
      .self$name &lt;- name
      .self$age &lt;- age
      .self$species &lt;- 'Canis familiaris'
    },
    show = function(.self){
      cat("The dog ", .self$name,
          " is ", .self$age)
    },
    validate = function(name, age){
      if (!is.character(name)){
        stop("name must be a character")
      }
      if (is.na(name)){
        stop("name cannot be NA")
      }
      if (!is.numeric(age)){
        stop("age must be a numeric")
      }
      if (is.na(age)){
        stop("age cannot be NA")
      }
      if (age&lt;0){
        stop("age cannot be &lt;0")
      }
    },
    updateAge = function(age){
      oldAge &lt;- .self$age
      .self$age &lt;- age
      return(oldAge)
    },
    humanAge = function(){
      return(.self$age*7)
    }
  )
)

newDog &lt;- Dog(name='Pluto', age = 4)
newDog$show()

The dog  Pluto  is  4

newDog$field('species')

[1] "Canis familiaris"

newDog$updateAge(5)

[1] 4

newDog$show()

The dog  Pluto  is  5

newDog$humanAge()

[1] 35


The way we define the class and its methods is identical to the way we defined Animals. However, since we used contains, Dog is a subclass of Animals. We can see this from the field species. We did not define species in fields, but we inherited it from Animals.
If we need to call a method from the superclass and resolve name conflicts, we can use the callSuper method.

#define the class
DogShow &lt;- setRefClass(
  "DogShow",
  contains = 'Animals',
  fields=c(name="character",
           age = 'numeric'),
  methods=list(
    initialize = function(name, age){
      .self$name &lt;- name
      .self$age &lt;- age
      .self$species &lt;- 'Canis familiaris'
    },
    show = function(){
      superClass()
    }
  )
)

newDog &lt;- Dog(name='Pluto', age = 4)
newDog$show()

The dog  Pluto  is  4


Note how the show method is inherited from Animals, and we call it from Dog using the superClass function.

Inheritance
R6 inheritance requires the use of the inherit argument in the class definition.

Dog &lt;- R6Class(
  'Dog',
  inherit = Animals,
  public = list(
    name = NULL,
    age = NULL,
    initialize = function(name, age){
      private$validate(name, age)
      self$species &lt;- 'Canis familiaris'
      self$age &lt;- age
      self$name &lt;- name
    },
    print = function(){
      cat("The dog ", self$name,
          " is ", self$age)
    },
    updateAge = function(age){
      oldAge &lt;- self$age
      self$age &lt;- age
      return(oldAge)
    },
    humanAge = function(){
      return(self$age * private$dog_human_age_ratio)
    }
  ),
  private = list(
    dog_human_age_ratio = 7,
    validate = function(name, age){
      if (!is.character(name)){
        stop("name must be a character")
      }
      if (is.na(name)){
        stop("name cannot be NA")
      }
      if (!is.numeric(age)){
        stop("age must be a numeric")
      }
      if (is.na(age)){
        stop("age cannot be NA")
      }
      if (age&lt;0){
        stop("age cannot be &lt;0")
      }
    },
    formatSpecies = function(species){
      return(stringr::str_to_sentence(species))
    }
  )
)

# usage
# create new object
newDog &lt;- Dog$new(name='Pluto', age=4)
newDog$print()

The dog  Pluto  is  4

newDog$humanAge()

[1] 28

newDog$updateAge(5)

[1] 4

newDog$print()

The dog  Pluto  is  5


We can access both public and private attributes of the superclass using super, as demonstrated in the example below.

DogShow &lt;- R6Class(
  "DogShow",
  inherit = Animals,
  public = list(
    name=NULL,
    age=NULL,
    initialize = function(name, age){
      self$name &lt;- name
      self$age &lt;- age
      self$species &lt;- 'Canis familaris'
    },
    # call the superclass method
    print = function(){
      super$print()
    }
  )
)

newDog &lt;- DogShow$new(name='Pluto', age=4)
newDog$print()

Object of class 'Animals'. The species is  Canis familaris

Update references

# main code to replace all references to templatedemo
replace_package_name(
    copied_files,
    basename(path),
    path
)

# utility funciton to loop through all the files we need to make replacements in
replace_package_name &lt;- function(copied_files,
                                 package_name,
                                 path){
  # Going through copied files to replace package name
  for (f in copied_files) {
    copied_file &lt;- file.path(path, f)

    try({
      replace_word(
        file = copied_file,
        pattern = "templatedemo",
        replace = package_name
      )
    },silent = TRUE)
  }
}

# utility funciton to make a replacement into a single file
replace_word &lt;- function (file, pattern, replace){
  suppressWarnings(tx &lt;- readLines(file))
  tx2 &lt;- gsub(pattern = pattern, replacement = replace, x = tx)
  writeLines(tx2, con = file)
}

# main code to replace all references to templatedemo
replace_package_name(
    copied_files,
    basename(path),
    path
  )

When we create the template, we put placeholders in place. For instance, in the DESCRIPTION file the name of the package is templatedemo. When a user creates a new project we replace all the placeholders with the actual name specified by the user. The snippet above accomplishes this. It gets a list of all files we copied over, then loops through them looking for the keyword templatedemo. The keyword is then replaced with the user’s new project name.

